=== file: main.loom ===
// Summarize an article into five bullets and independently verify their support.
// An unresolved finding is sent to a human reviewer; unverified bullets are never returned as verified.

budget { tokens: 12000  calls: 4 }

agent Summarizer {
    model: "gpt-6-luna"
    prompt: "summarizer"
    temperature: 0.2
    guard { pii: mask }
    output_schema: {
        bullet_1: string,
        bullet_2: string,
        bullet_3: string,
        bullet_4: string,
        bullet_5: string
    }
}

agent Verifier {
    model: "gpt-6-luna"
    prompt: "verifier"
    temperature: 0.1
    guard { pii: mask }
    output_schema: {
        status: enum["SUPPORTED", "UNSUPPORTED"],
        unsupported_bullets: string,
        evidence_notes: string
    }
}

agent Reviser {
    model: "gpt-6-luna"
    prompt: "reviser"
    temperature: 0.2
    guard { pii: mask }
    output_schema: {
        bullet_1: string,
        bullet_2: string,
        bullet_3: string,
        bullet_4: string,
        bullet_5: string
    }
}

workflow Main(supplied_article) {
    delegate "Summarize this article as exactly five concise bullet points:\n{supplied_article}" to Summarizer -> initial_bullet_set timeout 60s on_failure {
        halt "Summarizer failed: {_error}"
    }

    delegate "Check whether every proposed bullet is directly supported by the article. Article:\n{supplied_article}\n\nProposed bullets:\n1. {initial_bullet_set.bullet_1}\n2. {initial_bullet_set.bullet_2}\n3. {initial_bullet_set.bullet_3}\n4. {initial_bullet_set.bullet_4}\n5. {initial_bullet_set.bullet_5}" to Verifier -> initial_verification timeout 60s on_failure {
        halt "Initial verification failed: {_error}"
    }

    alt (initial_verification.status == "SUPPORTED") {
        return {
            status: "verified",
            bullet_1: "{initial_bullet_set.bullet_1}",
            bullet_2: "{initial_bullet_set.bullet_2}",
            bullet_3: "{initial_bullet_set.bullet_3}",
            bullet_4: "{initial_bullet_set.bullet_4}",
            bullet_5: "{initial_bullet_set.bullet_5}",
            verification_notes: "{initial_verification.evidence_notes}"
        }
    } else {
        delegate "Revise these five bullets using the article and verification findings. Article:\n{supplied_article}\n\nCurrent bullets:\n1. {initial_bullet_set.bullet_1}\n2. {initial_bullet_set.bullet_2}\n3. {initial_bullet_set.bullet_3}\n4. {initial_bullet_set.bullet_4}\n5. {initial_bullet_set.bullet_5}\n\nUnsupported bullets:\n{initial_verification.unsupported_bullets}\n\nEvidence notes:\n{initial_verification.evidence_notes}" to Reviser -> revised_bullet_set timeout 60s on_failure {
            halt "Revision failed: {_error}"
        }

        delegate "Check whether every revised bullet is directly supported by the article. Article:\n{supplied_article}\n\nProposed bullets:\n1. {revised_bullet_set.bullet_1}\n2. {revised_bullet_set.bullet_2}\n3. {revised_bullet_set.bullet_3}\n4. {revised_bullet_set.bullet_4}\n5. {revised_bullet_set.bullet_5}" to Verifier -> revised_verification timeout 60s on_failure {
            halt "Recheck failed: {_error}"
        }

        alt (revised_verification.status == "SUPPORTED") {
            return {
                status: "verified_after_revision",
                bullet_1: "{revised_bullet_set.bullet_1}",
                bullet_2: "{revised_bullet_set.bullet_2}",
                bullet_3: "{revised_bullet_set.bullet_3}",
                bullet_4: "{revised_bullet_set.bullet_4}",
                bullet_5: "{revised_bullet_set.bullet_5}",
                verification_notes: "{revised_verification.evidence_notes}"
            }
        } else {
            human_prompt "Human review required: support could not be established after the single revision and recheck. Review the article, revised bullets, and findings below. Provide your assessment or next steps.\n\nArticle:\n{supplied_article}\n\nRevised bullets:\n1. {revised_bullet_set.bullet_1}\n2. {revised_bullet_set.bullet_2}\n3. {revised_bullet_set.bullet_3}\n4. {revised_bullet_set.bullet_4}\n5. {revised_bullet_set.bullet_5}\n\nFindings:\n{revised_verification.unsupported_bullets}\n{revised_verification.evidence_notes}" -> reviewer_feedback

            return {
                status: "human_review_required",
                bullet_1: "{revised_bullet_set.bullet_1}",
                bullet_2: "{revised_bullet_set.bullet_2}",
                bullet_3: "{revised_bullet_set.bullet_3}",
                bullet_4: "{revised_bullet_set.bullet_4}",
                bullet_5: "{revised_bullet_set.bullet_5}",
                unsupported_bullets: "{revised_verification.unsupported_bullets}",
                verification_notes: "{revised_verification.evidence_notes}",
                reviewer_feedback: "{reviewer_feedback}"
            }
        }
    }
}
